    const h=createPressHandlers({open,preview});
    for(const [event,handler] of [['pointerdown',h.down],['pointermove',h.move],['pointerup',h.up],['pointerleave',h.cancel],['pointercancel',h.cancel],['click',h.click],['contextmenu',h.context]])button.addEventListener(event,handler,options);
    window.addEventListener('scroll',h.cancel,{...options,capture:true,passive:true});window.addEventListener('blur',h.cancel,options);window.addEventListener('pointerup',h.up,options);
    cleanups.push(h.cancel);
