  document.querySelectorAll('[data-repeat-food]').forEach(b=>b.onclick=()=>{const f=dayFor(state.data,state.date).food.find(x=>x.id===b.dataset.repeatFood);foodForm(null,{...f,id:undefined,loggedAt:undefined});});
