  document.querySelectorAll('[data-session]').forEach(b=>b.onclick=()=>workoutForm(null,b.dataset.session));
  document.querySelectorAll('[data-edit-workout]').forEach(b=>b.onclick=()=>{state.date=b.dataset.workoutDate;workoutForm(b.dataset.editWorkout);});
