async function action(id){if(id==='theme'){const current=document.documentElement.dataset.theme;return setTheme(state.theme==='system'?(current==='dark'?'light':'dark'):state.theme==='dark'?'light':'dark');}if(id==='home')return navigate('dashboard');if(id==='today')return selectDate(today(state.data.profile.timezone));if(id==='back'){if(window.history.state?.depth>0)window.history.back();else navigate(state.view);return;}if(id==='refresh')return load();if(id==='prev'||id==='next'){return selectDate(shiftDate(state.date,id==='prev'?-1:1));}if(id==='food')return foodForm();if(id==='workout')return workoutForm(null,state.detail?.type==='workout'?state.detail.id:undefined);if(['steps','water','weight','notes'].includes(id))return metricForm(id);if(id==='add')return showModal('Quick log',`<div class="choices">${[['food','Food or drink'],['workout','Workout'],['steps','Steps'],['water','Water'],['weight','Body weight'],['notes','Day notes']].map(([key,label])=>`<button class="choice" data-log="${key}">${icon(key==='workout'?'training':key)}${label}</button>`).join('')}</div>`,()=>modal.querySelectorAll('[data-log]').forEach(b=>b.onclick=()=>action(b.dataset.log)));if(id==='brief')return showModal('Your daily brief',`<p class="help">${esc(state.date)} · Totals from your saved record</p><pre class="notesbox">${esc(brief(state.data,state.date))}</pre><div class="modalactions"><button class="btn secondary" id="copybrief">Copy totals</button><button class="btn" id="printbrief">Print / save PDF</button></div>`,()=>{modal.querySelector('#copybrief').onclick=()=>copy(brief(state.data,state.date));modal.querySelector('#printbrief').onclick=()=>{afterClosingModal(()=>{navigate('dashboard');window.print();});};});if(id==='chat')return copy(`Use my fitness tracker in https://github.com/${REPO}. Read AGENTS.md and ${DATA_PATH} first. Log the following for ${state.date}, commit it, and send my updated daily totals and next workout: [tell you what I ate or did here]`);if(id==='export'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state.data,null,2)],{type:'application/json'}));a.download=`cams-health-${today()}.json`;a.click();URL.revokeObjectURL(a.href);}if(id==='disconnect'){state.token='';if(state.targetDirty){document.querySelector('#connect')?.reset();document.querySelector('#connect [data-action=disconnect]')?.remove();document.querySelector('#connect')?.closest('.card').querySelector('.statusbox').replaceChildren(document.createTextNode('Browser editing is disconnected. Your target changes are still here.'));}else{state.settingsDirty=false;render();}toast('Browser editing disconnected.');}}
