function metricForm(type){const config={steps:['Daily steps','steps','Total steps for the day',200000,1],water:['Water intake','waterMl','Total water today · ml',20000,1],weight:['Body weight','weightKg','Weight · kg',500,.1],notes:['Day notes','notes','Notes',0,0]}[type],date=state.date,[title,key,label,max,step]=config,value=dayFor(state.data,date)[key],baseline=value;showModal(title,`<form id="logform"><label class="field">${label}${type==='notes'?`<textarea name="value" maxlength="5000">${esc(value)}</textarea>`:`<input type="number" name="value" value="${value??''}" min="0" max="${max}" step="${step}" placeholder="Not logged">`}</label><p class="help">${type==='steps'||type==='water'?'Enter your total for the day. This replaces the existing total; it does not add to it.':type==='weight'?'Use a consistent measurement time. Blank removes the measurement.':'Saved with this date.'}</p>${authHelp()}<p class="formerror" id="formerror"></p><div class="modalactions"><button class="btn" type="submit">Save ${type}</button></div></form>`,()=>modal.querySelector('#logform').onsubmit=async e=>{e.preventDefault();const value=new FormData(e.target).get('value');await submit(()=>save(d=>{assertUnchanged(ensureDay(d,date)[key],baseline);ensureDay(d,date)[key]=type==='notes'?value:value===''?null:Number(value);},`Update ${type} for ${date}`));});}
