async function submit(fn){const form=modal.querySelector('form'),btn=form?.querySelector('[type=submit]');if(btn)btn.disabled=true;try{await fn();modal.close();}catch(error){const target=modal.querySelector('#formerror');if(target)target.textContent=error.message;else toast(error.message);}finally{if(btn)btn.disabled=false;}}
function confirmDelete(title,fn){showModal(title,'<p class="help">The current record will be removed. Previous versions remain in GitHub’s commit history.</p><p class="formerror" id="formerror"></p><div class="modalactions"><button class="btn secondary" id="canceldelete">Cancel</button><button class="btn danger" id="confirmdelete">Delete</button></div>',()=>{modal.querySelector('#canceldelete').onclick=()=>modal.close();modal.querySelector('#confirmdelete').onclick=async e=>{e.target.disabled=true;try{await fn();modal.close();}catch(error){modal.querySelector('#formerror').textContent=error.message;e.target.disabled=false;}};});}
